// Extended Euclidean Algorithm to find modular inverse
func modInverse(a, m int) int {
	g, x, _ := extendedGCD(a, m)
	if g != 1 {
		return -1 // No inverse exists
	}
	res := x % m
	if res < 0 {
		res += m
	}
	return res
}

func extendedGCD(a, b int) (gcd, x, y int) {
	if b == 0 {
		return a, 1, 0
	}
	gcd, x1, y1 := extendedGCD(b, a%b)
	x = y1
	y = x1 - (a/b)*y1
	return gcd, x, y
}
